package com.agriconnect.analytics; import jakarta.servlet.http.*; import java.util.*; import org.springframework.http.*; import org.springframework.web.bind.annotation.*; import org.springframework.web.client.*;
@RestController public class AnalyticsProxyController { private final RestClient core; AnalyticsProxyController(RestClient c){core=c;} private ResponseEntity<byte[]> get(String path,HttpServletRequest q){try{return core.get().uri(path+(q.getQueryString()==null?"":"?"+q.getQueryString())).header("Authorization",q.getHeader("Authorization")).header("X-Internal-Api-Key",System.getenv().getOrDefault("INTERNAL_API_KEY","local-dev-key")).retrieve().toEntity(byte[].class);}catch(ResourceAccessException e){throw new ServiceUnavailable("Core service timed out");}} @GetMapping("/api/dashboard") ResponseEntity<byte[]> dashboard(HttpServletRequest q){return get("/api/analytics/overview",q);} @GetMapping("/api/analytics/inventory-risk") ResponseEntity<byte[]> risk(HttpServletRequest q){return get("/api/inventory-risk-forecast",q);} @GetMapping("/api/analytics/rescue-priority") ResponseEntity<byte[]> rescue(HttpServletRequest q){return get("/api/analytics/congestion-risk",q);} @GetMapping("/api/analytics/production-forecast") ResponseEntity<byte[]> production(HttpServletRequest q){return get("/api/forecasts",q);} @GetMapping("/api/analytics/demand-forecast") ResponseEntity<byte[]> demand(HttpServletRequest q){return get("/api/analytics/forecast-inventory",q);} @GetMapping({"/api/analytics/**","/api/inventory-risk-forecast/**","/api/forecasts/**","/api/forecast-results/**","/api/forecast-dataset/**","/api/ai/**"}) ResponseEntity<byte[]> proxy(HttpServletRequest q){return get(q.getRequestURI(),q);} static class ServiceUnavailable extends RuntimeException{ServiceUnavailable(String m){super(m);}} }
